func _ready() -> void:
	populate_gallery()


func populate_gallery() -> void:
	if not grid_container:
		return

	for child in grid_container.get_children():
		child.queue_free()

	for item in GALLERY_CATALOG:
		var item_id: String = String(item.get("id", ""))
		var item_title: String = String(item.get("title", ""))
		var texture_path: String = String(item.get("texture_path", ""))

		var card := VBoxContainer.new()

		var tex_rect := TextureRect.new()
		tex_rect.custom_minimum_size = Vector2(128, 128)
		tex_rect.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		tex_rect.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED

		var label := Label.new()

		if UnlockManager and UnlockManager.is_image_unlocked(item_id):
