extends RefCounted


static func check_manifest(manifest_path: String = "res://release/release_manifest.json") -> Dictionary:
	var errors: Array[String] = []
	if not FileAccess.file_exists(manifest_path):
		errors.append("File manifesto non trovato: %s" % manifest_path)
		return {"valid": false, "errors": errors}

	var file := FileAccess.open(manifest_path, FileAccess.READ)
	if not file:
		errors.append("Impossibile leggere il file manifesto: %s" % manifest_path)
		return {"valid": false, "errors": errors}

	var parsed: Variant = JSON.parse_string(file.get_as_text())
	if not parsed is Dictionary:
		errors.append("Il manifesto non contiene un oggetto JSON valido")
		return {"valid": false, "errors": errors}

	var data: Dictionary = parsed
	var required_keys: Array[String] = [
		"title", "version", "project_type", "web_archive",
		"windows_archive", "description_file", "credits_file"
	]

	for req in required_keys:
		if not data.has(req) or String(data[req]).strip_edges().is_empty():
			errors.append("Chiave obbligatoria mancante o vuota: %s" % req)

	var ptype: String = String(data.get("project_type", ""))
	if ptype != "html":
		errors.append("Il tipo di progetto per itch.io deve essere 'html', trovato: '%s'" % ptype)

	var ver: String = String(data.get("version", ""))
	if not GameVersion.is_valid_semver(ver):
		errors.append("Versione non conforme allo standard semantico: '%s'" % ver)

	return {
		"valid": errors.is_empty(),
		"errors": errors
	}


static func check_web_archive_name(archive_name: String) -> bool:
	var prefix := "storie_v"
	var suffix := "_web.zip"
	if not archive_name.begins_with(prefix) or not archive_name.ends_with(suffix):
		return false

	var mid_len := archive_name.length() - prefix.length() - suffix.length()
	if mid_len <= 0:
		return false

	var ver_str := archive_name.substr(prefix.length(), mid_len)
	return GameVersion.is_valid_semver(ver_str)


static func audit_release_package(release_dir: String = "res://release/") -> Dictionary:
	var errors: Array[String] = []
	var checklist: Dictionary = {
		"manifest": false,
		"description": false,
		"credits": false,
		"version_match": false,
		"web_archive_name": false
	}

	var manifest_path: String = release_dir.path_join("release_manifest.json")
	var mres := check_manifest(manifest_path)
	if mres["valid"]:
		checklist["manifest"] = true
	else:
		for err in mres["errors"]:
			errors.append(err)

	var mfile := FileAccess.open(manifest_path, FileAccess.READ)
	var mdata: Dictionary = {}
	if mfile:
		var p: Variant = JSON.parse_string(mfile.get_as_text())
		if p is Dictionary:
			mdata = p

	var desc_name: String = String(mdata.get("description_file", "description.txt"))
	var desc_path: String = release_dir.path_join(desc_name)
	if FileAccess.file_exists(desc_path):
		var df := FileAccess.open(desc_path, FileAccess.READ)
		if df and df.get_as_text().length() >= 50:
			checklist["description"] = true
		else:
			errors.append("Il file di descrizione e vuoto o troppo breve")
	else:
		errors.append("File descrizione non trovato: %s" % desc_path)

	var cred_name: String = String(mdata.get("credits_file", "credits.txt"))
	var cred_path: String = release_dir.path_join(cred_name)
	if FileAccess.file_exists(cred_path):
		var cf := FileAccess.open(cred_path, FileAccess.READ)
		if cf and cf.get_as_text().contains("Godot"):
			checklist["credits"] = true
		else:
			errors.append("Il file crediti non menziona Godot Engine")
	else:
		errors.append("File crediti non trovato: %s" % cred_path)

	var mver: String = String(mdata.get("version", ""))
	var pver: String = GameVersion.get_version_string()
	if not mver.is_empty() and mver == pver:
		checklist["version_match"] = true
	else:
		errors.append("Discrepanza tra versione nel manifesto (%s) e ProjectSettings (%s)" % [mver, pver])

	var web_archive: String = String(mdata.get("web_archive", ""))
	if check_web_archive_name(web_archive):
		checklist["web_archive_name"] = true
	else:
		errors.append("Nome archivio Web non valido: %s" % web_archive)

	var all_passed := true
	for val in checklist.values():
		if not val:
			all_passed = false
			break

	return {
		"ready_to_publish": all_passed,
		"checklist": checklist,
		"errors": errors
	}
