"},{"percorso":"core/affinity_manager.gd","contenuto":"class_name AffinityManager
extends RefCounted

var _affinity_data: Dictionary = {}


func set_affinity(character_id: String, value: int) -> void:
	_affinity_data[character_id] = value


func get_affinity(character_id: String) -> int:
	return int(_affinity_data.get(character_id, 0))


func add_affinity(character_id: String, amount: int) -> void:
	var current: int = get_affinity(character_id)
	set_affinity(character_id, current + amount)


func has_character(character_id: String) -> bool:
	return _affinity_data.has(character_id)
"},{"percorso":"core/quick_save_manager.gd","contenuto":"class_name QuickSaveManager
extends RefCounted

const SAVE_PATH: String = "user://quicksave.json"


func quick_save(data: Dictionary) -> bool:
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if not file:
		return false
	var json_string := JSON.stringify(data)
	file.store_string(json_string)
	file.close()
	return true


func quick_load() -> Dictionary:
	if not has_quick_save():
		return {}
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if not file:
		return {}
	var content := file.get_as_text()
	file.close()
	var json := JSON.new()
	var err := json.parse(content)
	if err != OK or not (json.data is Dictionary):
		return {}
	return json.data as Dictionary


func has_quick_save() -> bool:
	return FileAccess.file_exists(SAVE_PATH)
"},{"percorso":"core/journal_manager.gd","contenuto":"class_name JournalManager
extends RefCounted

var _entries: Array[Dictionary] = []


func add_entry(entry_id: String, text: String) -> void:
	if has_entry(entry_id):
		return
	_entries.append({
		"id": entry_id,
		"text": text
	})


func has_entry(entry_id: String) -> bool:
	for item in _entries:
		if item.get("id", "") == entry_id:
			return true
	return false


func get_entries() -> Array[Dictionary]:
	return _entries.duplicate()


func clear_journal() -> void:
	_entries.clear()
"},{"percorso":"core/settings_manager.gd","contenuto":"extends Node

const SETTINGS_FILE := "user://settings.json"

var master_volume: float = 1.0
var sfx_volume: float = 1.0
var music_volume: float = 1.0
var current_language: String = "it"


func _ready() -> void:
	load_settings()


func set_language(lang: String) -> void:
	current_language = lang
	TranslationServer.set_locale(lang)
	save_settings()


func get_language() -> String:
	return current_language


func save_settings() -> void:
	var data := {
		"master_volume": master_volume,
		"sfx_volume": sfx_volume,
		"music_volume": music_volume,
		"language": current_language
	}
	var file := FileAccess.open(SETTINGS_FILE, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(data))
		file.close()


func load_settings() -> void:
	if not FileAccess.file_exists(SETTINGS_FILE):
		return
	var file := FileAccess.open(SETTINGS_FILE, FileAccess.READ)
	if not file:
		return
	var json := JSON.new()
	if json.parse(file.get_as_text()) == OK:
		var data: Dictionary = json.data
		master_volume = float(data.get("master_volume", 1.0))
		sfx_volume = float(data.get("sfx_volume", 1.0))
		music_volume = float(data.get("music_volume", 1.0))
		current_language = String(data.get("language", "it"))
		TranslationServer.set_locale(current_language)
	file.close()
"},{"percorso":"core/unlock_manager.gd","contenuto":"extends Node

const UNLOCKS_FILE := "user://unlocks.json"

var unlocked_gallery: Array[String] = []
var unlocked_endings: Array[String] = []


func _ready() -> void:
	load_unlocks()


func is_unlocked(id: String) -> bool:
	return unlocked_gallery.has(id) or unlocked_endings.has(id)


func unlock(id: String) -> void:
	if not is_unlocked(id):
		unlocked_endings.append(id)
		save_unlocks()


func save_unlocks() -> void:
	var data := {
		"gallery": unlocked_gallery,
		"endings": unlocked_endings
	}
	var file := FileAccess.open(UNLOCKS_FILE, FileAccess.WRITE)
	if file:
		file.store_string(JSON.stringify(data))
		file.close()


func load_unlocks() -> void:
	if not FileAccess.file_exists(UNLOCKS_FILE):
		return
	var file := FileAccess.open(UNLOCKS_FILE, FileAccess.READ)
	if not file:
		return
	var json := JSON.new()
	if json.parse(file.get_as_text()) == OK:
		var data: Dictionary = json.data
		unlocked_gallery = Array(data.get("gallery", []), TYPE_STRING, "", null)
		unlocked_endings = Array(data.get("endings", []), TYPE_STRING, "", null)
	file.close()
"},{"percorso":"ui/title_screen.tscn","contenuto":"[gd_scene format=3]

